const MZ_TR={'К':'K','П':'P','Л':'L','Б':'B','Е':'E','Н':'N','Р':'R'};function mzAid(id){return String(id||'').replace(/[^A-Za-z0-9_\-.~:@+]/g,c=>MZ_TR[c]||'x');}
function mzDefaults(){return MZ3;}
function esc(t){return String(t==null?'':t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function mzAll(){return (S.mzDb&&S.mzDb.length)?S.mzDb:MZ3;}
function mzGet(id){const a=mzAid(id);const all=mzAll();return all.find(z=>z.id===a)||all.find(z=>z.legacy===a)||null;}
function mzById(id){const z=mzGet(id);return z?{id:z.id,t:z.type,n:z.number,name:z.name,pts:z.polygon}:null;}
function mzCen(z){const p=z.labelPos||null;if(p)return p;const pts=z.polygon||[];if(pts.length<3){const a=pts[0]||[0,0],b=pts[pts.length-1]||a;return [(a[0]+b[0])/2,(a[1]+b[1])/2];}
  let A=0,x=0,y=0;for(let i=0;i<pts.length;i++){const [x0,y0]=pts[i],[x1,y1]=pts[(i+1)%pts.length];const f=x0*y1-x1*y0;A+=f;x+=(x0+x1)*f;y+=(y0+y1)*f;}if(Math.abs(A)<1e-6){const n=pts.length;return [pts.reduce((a,p)=>a+p[0],0)/n,pts.reduce((a,p)=>a+p[1],0)/n];}return [x/(3*A),y/(3*A)];}
function mzC(z){return mzCen({polygon:z.pts||z.polygon,labelPos:z.labelPos});}
function mzTaskable(z){return !!z&&!['poi','street','lm'].includes(z.type);}
function mzArea(r){let a=0;for(let i=0;i<r.length;i++){const p=r[i],q=r[(i+1)%r.length];a+=p[0]*q[1]-q[0]*p[1];}return Math.abs(a)/2;}
function tZones(t){return ((t.zones&&t.zones.length)?t.zones:(t.zone?[t.zone]:[])).map(id=>{const z=mzGet(id);return z?z.id:mzAid(id);});}
function mzTasksAll(id){return S.tasks.filter(t=>tZones(t).includes(id));}
function mzTasks(id){return mzTasksAll(id).filter(t=>!isDone(t));}
function mzStatus(id){const today=ymd(new Date());const L=mzTasksAll(id);const open=L.filter(t=>!isDone(t));
  if(open.some(t=>t.due&&t.due<today))return 'over';if(open.length)return 'open';if(L.some(t=>isDone(t)&&t.doneAt&&ymd(new Date(t.doneAt))===today))return 'done';return 'none';}
function canZoneEdit(){return isDev();}
function mapOpen(){return isDev();}
function zoneTag(t){const zs=tZones(t).map(mzById).filter(Boolean);if(!zs.length)return null;const z=zs[0];const txt=zs.length>1?'Зони '+zs.map(x=>x.n).join(', '):z.name;
  if(!mapOpen())return el('span',{class:'zone-tag t-'+z.t},el('i'),txt);
  return el('button',{type:'button',class:'zone-tag t-'+z.t,title:'Показати на карті',onclick:e=>{e.stopPropagation();S.mzSel=z.id;S.mzMulti=null;S.mzFocus=z.id;go('map');}},el('i'),txt,' · на карті');}
