function mzLeaflet(){if(window.L&&L.CRS)return Promise.resolve();return _mzLeaf||(_mzLeaf=mzScript(MZ_LIB.leaflet).catch(e=>{_mzLeaf=null;throw e;}));}
function mzGeoman(){return mzLeaflet().then(()=>(L.PM?null:(_mzGeo||(_mzGeo=mzScript(MZ_LIB.geoman).catch(e=>{_mzGeo=null;throw e;}))))).then(()=>{if(MZM&&!MZM.map.pm&&L.PM&&L.PM.Map){MZM.map.pm=new L.PM.Map(MZM.map);}if(MZM&&MZM.map.pm)MZM.map.pm.setGlobalOptions({snappable:true,snapDistance:14,allowSelfIntersection:false});});}
function mzTurfLib(){if(window.turf)return Promise.resolve();return _mzTurf||(_mzTurf=mzScript(MZ_LIB.turf).catch(e=>{_mzTurf=null;throw e;}));}
/* --- геометрія --- */
const LL=p=>[MZ_H-p[1],p[0]];
const PX=ll=>[Math.round(ll.lng*100)/100,Math.round((MZ_H-ll.lat)*100)/100];
function mzLatLngs(z){const main=[z.polygon,...(z.holes||[])].map(r=>r.map(LL));const ex=(z.extra||[]).map(rs=>rs.map(r=>r.map(LL)));return ex.length?[main,...ex]:main;}
function mzFromLayer(layer){let ll=layer.getLatLngs();if(!Array.isArray(ll[0]))ll=[ll];if(!Array.isArray(ll[0][0]))ll=[ll];
  const polys=ll.map(rs=>rs.map(r=>r.map(PX))).filter(rs=>rs[0]&&rs[0].length>=3).sort((a,b)=>mzArea(b[0])-mzArea(a[0]));
  if(!polys.length)return null;const [m,...ex]=polys;return {polygon:m[0],holes:m.slice(1),extra:ex};}
function mzFeat(g){const close=r=>{const c=r.map(p=>[p[0],p[1]]);c.push([r[0][0],r[0][1]]);return c;};const main=[close(g.polygon),...(g.holes||[]).map(close)];
  const ex=(g.extra||[]).map(rs=>rs.map(close));return ex.length?turf.multiPolygon([main,...ex]):turf.polygon(main);}
function mzFromFeat(f){if(!f||!f.geometry)return null;const g=f.geometry;const ps=(g.type==='Polygon'?[g.coordinates]:g.coordinates).map(rs=>rs.map(r=>r.slice(0,-1).map(p=>[Math.round(p[0]*100)/100,Math.round(p[1]*100)/100])))
  .filter(rs=>rs[0].length>=3).sort((a,b)=>mzArea(b[0])-mzArea(a[0]));if(!ps.length)return null;const [m,...ex]=ps;return {polygon:m[0],holes:m.slice(1),extra:ex};}
function mzGArea(g){return mzArea(g.polygon)-(g.holes||[]).reduce((a,h)=>a+mzArea(h),0)+(g.extra||[]).reduce((a,rs)=>a+mzArea(rs[0]),0);}
function mzBox(g){const xs=[],ys=[];[g.polygon,...(g.extra||[]).map(r=>r[0])].forEach(r=>r.forEach(p=>{xs.push(p[0]);ys.push(p[1]);}));return [Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)];}
/* перетини з іншими зонами (Turf intersect), площа в px² */
function mzConflicts(g,selfId){const b=mzBox(g);const out=[];const f=mzFeat(g);
  for(const z of mzAll()){if(z.id===selfId||!z.polygon||z.polygon.length<3)continue;const c=mzBox(z);if(c[0]>b[2]||c[2]<b[0]||c[1]>b[3]||c[3]<b[1])continue;
    let x=null;try{x=turf.intersect(turf.featureCollection([f,mzFeat(z)]));}catch(e){}const a=x?mzGArea(mzFromFeat(x)||{polygon:[]}):0;if(a>0.05)out.push({z,a});}
  return out.sort((p,q)=>q.a-p.a);}
